		return false, err
	}
	if len(shallow) == 0 {
		return false, nil
	}
	for _, h := range hashes {
		if h == "" {
			continue
		}
		for boundary := range shallow {
			reachable, ancErr := isAncestor(ctx, repoPath, boundary.String(), h)
			if ancErr != nil {
				return false, ancErr
			}
			if reachable {
				return true, nil
			}
		}
	}
	return false, nil
}

// isAncestor reports whether ancestorHash is reachable from descendantHash
// (inclusive) using `git merge-base --is-ancestor`.
//
// Exit codes: 0 = ancestor, 1 = not an ancestor, other = error.
func isAncestor(ctx context.Context, repoPath, ancestorHash, descendantHash string) (bool, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", "merge-base", "--is-ancestor", ancestorHash, descendantHash)
	cmd.Dir = repoPath
	if err := cmd.Run(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
			return false, nil
		}
		return false, fmt.Errorf("git merge-base --is-ancestor: %w", err)
	}
	return true, nil
}

// MetadataHistoryShallowBounded reports whether the local primary metadata ref
// or its origin remote-tracking ref has a shallow boundary in its ancestry —
// i.e. whether deepening the metadata branch could change a merge-base result.
//
// 'entire doctor' uses this to decide whether to deepen before the disconnection
// check, so it never issues a (potentially large) deepen for a shallow boundary
// that belongs to an unrelated branch such as a shallow source-tree clone.
func MetadataHistoryShallowBounded(ctx context.Context, repo *git.Repository) (bool, error) {
	repoPath, err := getRepoPath(repo)
	if err != nil {
		return false, err
	}
	refs := checkpoint.ResolveCommittedRefs(ctx)

	var hashes []string
	addRef := func(name plumbing.ReferenceName) {
		if ref, refErr := repo.Reference(name, true); refErr == nil {
			hashes = append(hashes, ref.Hash().String())
		}
	}
	addRef(refs.Primary)
	if refs.PrimaryFetchableFromOrigin() {
		addRef(plumbing.NewRemoteReferenceName("origin", refs.Primary.Short()))
	}
	if len(hashes) == 0 {
		return false, nil
	}
	return historyReachesShallowBoundary(ctx, repoPath, hashes...)
}

