// We therefore only treat a merge-base miss as a genuine disconnection when the
// metadata history does not reach a shallow boundary. The check is keyed on the
// metadata commits specifically (not merely "is the repo shallow"), so a
// genuine disconnection on a repo that is shallow only for an unrelated
// source-tree branch is still reported. When the metadata history is
// shallow-bounded the verdict is suppressed (refs reported connected) and
// 'entire doctor' is the path that deepens the branch and re-checks.
func metadataDisconnected(ctx context.Context, repoPath, localHash, remoteHash string) (bool, error) {
	disconnected, err := isDisconnected(ctx, repoPath, localHash, remoteHash)
	if err != nil {
		return false, err
	}
	if !disconnected {
		return false, nil
	}
	bounded, err := historyReachesShallowBoundary(ctx, repoPath, localHash, remoteHash)
	if err != nil {
		return false, err
	}
	if bounded {
		logging.Debug(ctx, "merge-base reports no common ancestor but metadata history reaches a "+
			"shallow boundary; treating refs as connected (run 'entire doctor' to deepen and re-check)",
			slog.String("local", localHash),
			slog.String("remote", remoteHash))
		return false, nil
	}
	return true, nil
}

// historyReachesShallowBoundary reports whether any of the given commits has a
// shallow-boundary commit in its ancestry — i.e. whether the visible history of
// those commits is truncated by .git/shallow. A merge-base miss is only
// trustworthy when this is false.
func historyReachesShallowBoundary(ctx context.Context, repoPath string, hashes ...string) (bool, error) {
	shallow, err := loadShallowHashes(ctx, repoPath)
	if err != nil {
		return false, err
	}
	if len(shallow) == 0 {
		return false, nil
	}
	for _, h := range hashes {
		if h == "" {
			continue
		}
		for boundary := range shallow {
			reachable, ancErr := isAncestor(ctx, repoPath, boundary.String(), h)
			if ancErr != nil {
				return false, ancErr
			}
			if reachable {
				return true, nil
			}
		}
	}
	return false, nil
}

// isAncestor reports whether ancestorHash is reachable from descendantHash
// (inclusive) using `git merge-base --is-ancestor`.
//
// Exit codes: 0 = ancestor, 1 = not an ancestor, other = error.
func isAncestor(ctx context.Context, repoPath, ancestorHash, descendantHash string) (bool, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", "merge-base", "--is-ancestor", ancestorHash, descendantHash)
	cmd.Dir = repoPath
	if err := cmd.Run(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
			return false, nil
		}
		return false, fmt.Errorf("git merge-base --is-ancestor: %w", err)
	}
