// FetchMetadataTreeOnly fetches just the tip of the entire/checkpoints/v1
// branch (--depth=1). Used by resume/explain to resolve the latest checkpoint
// cheaply without pulling the entire history.
//
// The shallow tip is fetched into a throwaway ref rather than
// refs/remotes/origin/<branch>: a --depth=1 fetch truncates the tip's ancestry,
// and pointing the durable remote-tracking ref at a truncated tip is what makes
// later `git merge-base` disconnection checks (push / doctor) falsely report
// "no common ancestor" (see strategy.IsMetadataDisconnected). The local primary
// ref is still advanced — but SafelyAdvanceLocalRef refuses to fast-forward
// across an unprovable shallow boundary, so it can't be poisoned the same way.
// May leave .git/shallow set; FetchMetadataBranch fetches full ancestry when
// it's later needed.
func FetchMetadataTreeOnly(ctx context.Context) error {
	return fetchMetadataFromOrigin(ctx, fetchMetadataOpts{Shallow: true})
}

type fetchMetadataOpts struct {
	NoFilter  bool
	Shallow   bool
	Unshallow bool
}

func fetchMetadataFromOrigin(ctx context.Context, fopts fetchMetadataOpts) error {
	refs := checkpoint.ResolveCommittedRefs(ctx)
	if !refs.Primary.IsBranch() {
		return fmt.Errorf("primary metadata ref %s is not a branch", refs.Primary)
	}
	branchName := refs.Primary.Short()

	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	fetchTarget, err := remote.ResolveFetchTarget(ctx, "origin")
	if err != nil {
		return fmt.Errorf("failed to resolve fetch target: %w", err)
	}

	// A shallow tip-only fetch lands in a throwaway ref so the truncated tip
	// never advances the durable remote-tracking ref; full fetches update
	// refs/remotes/origin/<branch> as usual.
	destRef := plumbing.NewRemoteReferenceName("origin", branchName)
	if fopts.Shallow {
		destRef = plumbing.ReferenceName(strategy.FetchTmpRefPrefix + branchName)
	}
	refSpec := fmt.Sprintf("+refs/heads/%s:%s", branchName, destRef.String())

	output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
		Remote:    fetchTarget,
		RefSpecs:  []string{refSpec},
		NoTags:    true,
		NoFilter:  fopts.NoFilter,
		Shallow:   fopts.Shallow,
		Unshallow: fopts.Unshallow,
	})
	if fetchErr != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return errors.New("fetch timed out after 2 minutes")
		}
		return formatFilteredFetchError("failed to fetch "+branchName, fetchTarget, output, fetchErr)
	}

	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}
	defer repo.Close()

	fetchedRef, err := repo.Reference(destRef, true)
	if err != nil {
		return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
	}
	if err := strategy.SafelyAdvanceLocalRef(ctx, repo, refs.Primary, fetchedRef.Hash()); err != nil {
		return fmt.Errorf("failed to advance local %s branch: %w", branchName, err)
	}

