package cli

import (
	"context"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// TestFetchMetadataTreeOnly_DoesNotPoisonOriginRef is a regression test for the
// shallow-metadata false-disconnect.
//
// FetchMetadataTreeOnly does a --depth=1 fetch to cheaply read the latest
// checkpoint tree. Previously it landed that truncated tip on the durable
// remote-tracking ref refs/remotes/origin/entire/checkpoints/v1. Once that ref
// pointed at a shallow tip, a later `git merge-base` against it could no longer
// reach the real common ancestor (it's below the shallow boundary) and the
// disconnection check falsely reported "no common ancestor" — aborting push and
// looping doctor.
//
// The fix lands the shallow tip in a throwaway ref instead, leaving the durable
// remote-tracking ref untouched, while still advancing the local primary ref so
// reads work.
func TestFetchMetadataTreeOnly_DoesNotPoisonOriginRef(t *testing.T) {
	// Uses t.Chdir() — cannot run in parallel.

	tmpDir := t.TempDir()
	bareDir := filepath.Join(tmpDir, "bare.git")
	localDir := filepath.Join(tmpDir, "local")

	runGit(t, tmpDir, "init", "--bare", bareDir)

	// Seed repo: a main commit plus an orphan metadata branch with its own
	// checkpoint commit, both pushed to the bare origin.
	testutil.InitRepo(t, localDir)
	testutil.WriteFile(t, localDir, "README.md", "hello")
	testutil.GitAdd(t, localDir, "README.md")
	testutil.GitCommit(t, localDir, "init")
	runGit(t, localDir, "remote", "add", "origin", bareDir)
	runGit(t, localDir, "checkout", "--orphan", paths.MetadataBranchName)
	runGit(t, localDir, "rm", "-rf", ".")
	testutil.WriteFile(t, localDir, "metadata.json", `{"checkpoint_id":"deadbeef0001"}`)
	testutil.GitAdd(t, localDir, "metadata.json")
	testutil.GitCommit(t, localDir, "Checkpoint: deadbeef0001")
	runGit(t, localDir, "checkout", "main")
	runGit(t, localDir, "push", "origin", "HEAD:refs/heads/main", paths.MetadataBranchName)
	runGit(t, bareDir, "symbolic-ref", "HEAD", "refs/heads/main")

	originTip := gitRevParse(t, bareDir, "refs/heads/"+paths.MetadataBranchName)

	// Fresh clone of main only — it has no metadata branch and no
	// origin/<metadata> remote-tracking ref yet.
	clonedDir := filepath.Join(tmpDir, "cloned")
	runGit(t, tmpDir, "clone", "--branch", "main", bareDir, clonedDir)
	runGit(t, clonedDir, "config", "user.email", "test@example.com")
	runGit(t, clonedDir, "config", "user.name", "Test")

	t.Chdir(clonedDir)

	if err := FetchMetadataTreeOnly(t.Context()); err != nil {
		t.Fatalf("FetchMetadataTreeOnly: %v", err)
	}

	originRef := "refs/remotes/origin/" + paths.MetadataBranchName
	tmpRef := strategy.FetchTmpRefPrefix + paths.MetadataBranchName
	localRef := "refs/heads/" + paths.MetadataBranchName

	// The durable remote-tracking ref must NOT have been created/advanced to the
	// shallow tip — that is the poison this fix removes.
	if err := runGitAllow(t, clonedDir, "rev-parse", "--verify", "--quiet", originRef); err == nil {
		got := gitRevParse(t, clonedDir, originRef)
		t.Errorf("%s was advanced to %s by a tree-only fetch; the truncated tip must not land on the durable remote-tracking ref", originRef, got)
	}

	// The tip is still fetched — into the throwaway ref — so reads work.
	if got := gitRevParse(t, clonedDir, tmpRef); got != originTip {
		t.Errorf("throwaway ref %s = %q, want origin tip %q", tmpRef, got, originTip)
	}

	// The local primary ref is advanced so resume/attach can read the tip.
	if got := gitRevParse(t, clonedDir, localRef); got != originTip {
		t.Errorf("local primary ref %s = %q, want origin tip %q", localRef, got, originTip)
	}
}

func gitRevParse(t *testing.T, dir, rev string) string {
	t.Helper()
	cmd := exec.CommandContext(context.Background(), "git", "rev-parse", rev)
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("git rev-parse %s in %s: %v", rev, dir, err)
	}
	return strings.TrimSpace(string(out))
}

