		t.Errorf("throwaway ref %s = %q, want origin tip %q", tmpRef, got, originTip)
	}

	// The local primary ref is advanced so resume/attach can read the tip.
	if got := gitRevParse(t, clonedDir, localRef); got != originTip {
		t.Errorf("local primary ref %s = %q, want origin tip %q", localRef, got, originTip)
	}
}

func gitRevParse(t *testing.T, dir, rev string) string {
	t.Helper()
	cmd := exec.CommandContext(context.Background(), "git", "rev-parse", rev)
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("git rev-parse %s in %s: %v", rev, dir, err)
	}
	return strings.TrimSpace(string(out))
}

