24		if isFetchTargetURL(fetchTarget) {
25			redactedTarget = remote.RedactURL(fetchTarget)
26		}
27	
28		msg := strings.TrimSpace(string(output))
29		if isFetchTargetURL(fetchTarget) {
30			msg = strings.TrimSpace(strings.ReplaceAll(msg, fetchTarget, redactedTarget))
31		}
32		if msg != "" {
33			return fmt.Errorf("%s from %s: %s: %w", prefix, redactedTarget, msg, fetchErr)
34		}
35		return fmt.Errorf("%s from %s: %w", prefix, redactedTarget, fetchErr)
36	}
37	
38	func isFetchTargetURL(target string) bool {
39		return strings.Contains(target, "://") || strings.Contains(target, "@")
40	}
41	
42	// openRepository opens the git repository with linked worktree support enabled.
43	// This is a convenience wrapper around strategy.OpenRepository() for use in the CLI package.
44	func openRepository(ctx context.Context) (*git.Repository, error) {
45		repo, err := strategy.OpenRepository(ctx)
46		if err != nil {
47			return nil, fmt.Errorf("failed to open repository: %w", err)
48		}
49		return repo, nil
50	}
51	
52	// GitAuthor represents the git user configuration
53	type GitAuthor struct {
54		Name  string
55		Email string
56	}
57	
58	// GetGitAuthor retrieves the git user.name and user.email from the repository config.
59	// It checks local config first, then falls back to global config.
60	// If go-git can't find the config, it falls back to using the git command.
61	// Returns fallback defaults if no user is configured anywhere.
62	func GetGitAuthor(ctx context.Context) (*GitAuthor, error) {
63		repo, err := openRepository(ctx)
64		if err != nil {
65			return nil, fmt.Errorf("failed to open git repository: %w", err)
66		}
67		defer repo.Close()
68	
69		name, email := strategy.GetGitAuthorFromRepo(repo)
70	
71		// If go-git returned defaults, try using git command as fallback
72		// This handles cases where go-git can't find the config (e.g., different HOME paths,
73		// non-standard config locations, or environment issues in hook contexts)
74		if name == "Unknown" {
75			if gitName := getGitConfigValue(ctx, "user.name"); gitName != "" {
76				name = gitName
77			}
78		}
79		if email == "unknown@local" {
80			if gitEmail := getGitConfigValue(ctx, "user.email"); gitEmail != "" {
81				email = gitEmail
82			}
83		}
84	
85		return &GitAuthor{
86			Name:  name,
87			Email: email,
88		}, nil
89	}
