102	// IsOnDefaultBranch checks if the repository is currently on the default branch.
103	// It determines the default branch by:
104	// 1. Checking the remote origin's HEAD reference
105	// 2. Falling back to common names (main, master) if remote HEAD is unavailable
106	// Returns (isDefault, branchName, error)
107	func IsOnDefaultBranch(ctx context.Context) (bool, string, error) {
108		repo, err := openRepository(ctx)
109		if err != nil {
110			return false, "", fmt.Errorf("failed to open git repository: %w", err)
111		}
112		defer repo.Close()
113	
114		// Get current branch
115		head, err := repo.Head()
116		if err != nil {
117			return false, "", fmt.Errorf("failed to get HEAD: %w", err)
118		}
119	
120		if !head.Name().IsBranch() {
121			// Detached HEAD - not on any branch
122			return false, "", nil
123		}
124	
125		currentBranch := head.Name().Short()
126	
127		// Try to get default branch from remote origin's HEAD
128		defaultBranch := getDefaultBranchFromRemote(repo)
129	
130		// If we couldn't determine from remote, use common defaults
131		if defaultBranch == "" {
132			// Check if current branch is a common default name
133			if currentBranch == defaultBaseBranch || currentBranch == masterBaseBranch {
134				return true, currentBranch, nil
135			}
136			return false, currentBranch, nil
137		}
138	
139		return currentBranch == defaultBranch, currentBranch, nil
140	}
