142	// getDefaultBranchFromRemote tries to determine the default branch from the origin remote.
143	// Returns empty string if unable to determine.
144	func getDefaultBranchFromRemote(repo *git.Repository) string {
145		// Try to get the symbolic reference for origin/HEAD
146		ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
147		if err == nil && ref != nil {
148			// ref.Target() gives us something like "refs/remotes/origin/main"
149			target := ref.Target().String()
150			if strings.HasPrefix(target, "refs/remotes/origin/") {
151				return strings.TrimPrefix(target, "refs/remotes/origin/")
152			}
153		}
154	
155		// Fallback: check if origin/main or origin/master exists
156		if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", defaultBaseBranch), true); err == nil {
157			return defaultBaseBranch
158		}
159		if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", masterBaseBranch), true); err == nil {
160			return masterBaseBranch
161		}
162	
163		return ""
164	}
